div.script:
(function() {
  function initFallbackWizard() {
    function localGoToStep(num) {
      if (window.netspoutGoToStep) {
        window.netspoutGoToStep(num);
        return;
      }
      for (var i = 1; i <= 4; i++) {
        var c = document.getElementById('container-step-' + i);
        if (c) c.style.display = (i === num ? 'block' : 'none');
        var b = document.getElementById('badge-step-' + i);
        if (b) {
          if (i === num) {
            b.style.background = '#0284c7'; b.style.color = '#ffffff';
          } else if (i < num) {
            b.style.background = '#14532d'; b.style.color = '#4ade80';
          } else {
            b.style.background = '#1e293b'; b.style.color = '#94a3b8';
          }
        }
      }
    }

    // Attach fallbacks
    var next1 = document.getElementById('btn-next-step-1');
    if (next1) next1.onclick = function() { localGoToStep(2); };
    var back2 = document.getElementById('btn-back-step-2');
    if (back2) back2.onclick = function() { localGoToStep(1); };
    var next2 = document.getElementById('btn-next-step-2');
    if (next2) next2.onclick = function() { localGoToStep(3); };
    var back3 = document.getElementById('btn-back-step-3');
    if (back3) back3.onclick = function() { localGoToStep(2); };
    var next3 = document.getElementById('btn-next-step-3');
    if (next3) next3.onclick = function() { localGoToStep(4); };
    var back4 = document.getElementById('btn-back-step-4');
    if (back4) back4.onclick = function() { localGoToStep(3); };

    // Stepper badges
    for (var j = 1; j <= 4; j++) {
      (function(step) {
        var b = document.getElementById('badge-step-' + step);
        if (b) b.onclick = function() { localGoToStep(step); };
      })(j);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initFallbackWizard);
  } else {
    initFallbackWizard();
  }
  setTimeout(initFallbackWizard, 250);
  setTimeout(initFallbackWizard, 1000);
})();
